fn main(){use serde_json::json;use std::time::Instant;let mut seed=before::State::new().unwrap();for i in 0..4000u64{seed.invoke_json("put",&json!([i,i,i%2==0,false])).unwrap();}seed.acknowledge_through(u64::MAX,u64::MAX);let initial=seed.checkpoint().unwrap();let mut samples=vec![];for _ in 0..5{let old=before::State::restore(&initial).unwrap();let start=Instant::now();let bytes=old.checkpoint().unwrap();let next=after::State::restore(&bytes).unwrap();drop(old);samples.push(start.elapsed().as_nanos().to_string());assert_eq!(next.checkpoint().unwrap(),bytes);}println!("{}",serde_json::to_string(&samples).unwrap());}
